+// ─── Inline content path ─────────────────────────────────────────────────────
+
+describe("FeatureTasksPanel — inline content path", () => {
+  it("passes inline content to useDocumentContent when present", () => {
+    const inlineContent = "# Inline tasks.md\n\nLoaded from backend.";
